import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 40 · Christmas tips: garland, mantel and staircase mistakes (Google Trends 3/11: christmas decorations rising, Pottery Barn, vintage, nordic)
# Grandma Ruth: born 1944 in Mansfield, Ohio; mother Dorothy, father Walter, brother Danny, Grandma Pearl.

sc("""Sweetheart, you can always tell a home that's been decorated with love from one that's been decorated from a box. And most of the time, the difference is the garland. That long rope of green over the fireplace, or up the stairs, or around the door. Done right, it makes a room look like a Christmas card. Done wrong, it looks like a sad green snake.""",
   "Christmas mantel garland fireplace", "A SAD GREEN SNAKE")
sc("""So tonight I'm giving you seven Christmas garland mistakes that make a home look cheap, and the old fixes my mother used, most of them free. And stay with me, because the last one is the trick decorators charge hundreds of dollars for, and you can do it this weekend with branches from your own yard.""",
   "thick lush garland staircase", "SEVEN GARLAND MISTAKES")

ch("Mother's mantel")
sc("""We didn't have a fireplace on Elm Street. We had a coal furnace in the basement. But my mother made a mantel anyway, on the top of the old upright piano in the front room. Every December, she draped it with cedar branches my father cut from the fencerow, with pinecones and a row of little red candles, and our family photographs in the middle.""",
   "old upright piano Christmas greenery", "A MANTEL ON THE PIANO")
sc("""She never bought a single thing for it. And when the piano teacher came on Thursdays, she'd stand in the doorway and say, Dorothy, your piano looks like a magazine. My mother would say, it's just branches, Mrs. Fenwick. But she was proud, honey. I could tell, because she dusted the piano twice that week.""",
   "1950s woman dusting piano", "LIKE A MAGAZINE")

sc("""Before you start, measure, honey. A garland for a mantel should be about one and a half times the width of the mantel, so it has enough to drape down the sides. For a staircase, measure the rail and add a third. Most people buy one six-foot garland for a five-foot mantel, and that's where the trouble starts. In a minute you'll see why.""",
   "measuring tape mantel width", "MEASURE FIRST")

ch("1. Too thin")
sc("""Mistake number one. A thin garland. Most store garland is skinny and flat, like a pipe cleaner. Stretched across a mantel, it looks like you ran out of money in the middle of decorating. A garland should be big and full, eight or ten inches thick, with branches sticking out in every direction. Fullness is what makes it look rich.""",
   "thin skinny garland mantel", "LIKE A PIPE CLEANER")
sc("""Here's the free fix. Take two or three cheap garlands and twist them together into one, and fluff every branch out with your fingers, up, down and sideways. It takes an hour, but it doubles the size. My mother would put the radio on and fluff for a whole afternoon, singing along with Bing Crosby.""",
   "fluffing garland branches hands", "FLUFF EVERY BRANCH")

ch("2. All one kind")
sc("""Mistake number two. All fake and all one kind. A plastic garland, all the same green, all the same shape, looks like plastic from across the room. The fix is to tuck in real branches. Cedar, pine, spruce, boxwood, holly, eucalyptus. Mix two or three kinds. The different shapes and greens make it look natural, and the real ones make the whole house smell like Christmas.""",
   "mixed real evergreen branches", "MIX THE GREENS")
sc("""And here's where you get them free, honey. The Christmas tree lot trims the bottom branches off every tree they sell, and they throw them in a pile in the back. Just ask. They'll give you an armful, and sometimes they'll even help you to the car. Real branches stay fresh about two weeks indoors, away from the heat. Mist them with water every couple of days.""",
   "Christmas tree lot branches pile", "JUST ASK")

ch("3. Hanging straight")
sc("""Mistake number three. Hanging it straight and flat, like a shelf. A garland across a mantel should drape a little, or hang down at both ends, longer on the sides than in the middle. Let the ends fall about a third of the way down the sides of the fireplace. That loose, generous look is what you see in the fancy catalogs.""",
   "garland draping mantel sides", "LET THE ENDS FALL")
sc("""If this is helping you, honey, tap the like button for me. It helps Grandma more than you know. And how do you hang it without nails in your mantel? Command hooks on the underside, or a heavy book or a brick at each end on top, with the garland tied to it with wire and hidden under the branches. My father used two bricks wrapped in green felt.""",
   "hooks hanging garland mantel", "TWO BRICKS IN FELT")

ch("4. No lights inside")
sc("""Mistake number four. Lights wrapped around the outside of the garland, like a candy cane stripe. You see the wires and the plugs, and it looks cheap. Here's the fix. Tuck the lights deep inside the garland, pushing the strands into the middle of the branches. Then it glows from inside, softly, like a fire. And use warm white lights, never the cold blue ones.""",
   "warm lights inside garland glowing", "GLOWS FROM INSIDE")
sc("""And use more lights than you think, sweetheart. One hundred little lights for every six feet of garland. That sounds like a lot, but tucked deep in the branches, it's just right. Buy the ones on a battery pack with a timer, and hide the battery box behind a picture frame or a candle. Then there's no cord hanging down to the floor for the cat to chew.""",
   "battery string lights timer", "MORE LIGHTS")

ch("5. Too much stuff")
sc("""So far, make it full, mix real greens in, let it drape, and tuck the lights inside. Now mistake number five. Too many things stuck in it. Ornaments, ribbons, signs, little figures, all different colors. It looks like a junk drawer. Pick two or three things and repeat them all along the garland. Pinecones, red berries, and a few gold ornaments, for example.""",
   "cluttered mantel decorations", "LIKE A JUNK DRAWER")
sc("""Repetition is the secret, honey. The same three things, over and over, every eight or ten inches. Your eye reads it as a pattern, and a pattern looks expensive. My mother used pinecones, red candles and dried orange slices. Three things. Every year the same. And every year, somebody asked her who decorated the piano.""",
   "pinecones red berries garland pattern", "REPEAT THREE THINGS")
sc("""And here's how to dry orange slices for free. Slice oranges thin, a quarter inch, and pat them dry with a towel. Lay them on a rack over a baking sheet and bake at two hundred degrees for about three hours, turning them every hour, until they're dry like stained glass. Hold one up to the window, and the light shines right through it.""",
   "dried orange slices stained glass", "LIKE STAINED GLASS")

ch("6. The bare staircase")
sc("""Mistake number six. A bare stair rail, or a garland wrapped round and round it like a barber pole. The old way is better. Lay the garland along the top of the rail, and tie it with ribbon or twine every two or three feet. Then let it swag down a little between the ties, like a smile. Put a bow at every tie, or just at the top and bottom.""",
   "garland swag staircase bows", "LIKE A SMILE")
sc("""And be careful, honey. Never cover the part of the rail where people's hands go. Leave the top of the rail clear, and tie the garland on the outside of the posts. My granddaughter Emily nearly went down the stairs on Christmas morning because of a garland, with a cup of coffee in her hand. Safety first, then pretty.""",
   "hand on stair rail garland outside", "SAFETY FIRST")

ch("7. The decorator's trick")
sc("""And now mistake number seven, the trick decorators charge hundreds of dollars for. Forgetting the height. A garland all alone on a mantel, flat and low, looks small. The decorators add tall things. Two tall vases, one at each end, full of tall branches. Or big candlesticks, or a pair of little potted trees. Now the eye goes up, and the whole wall looks grand.""",
   "mantel tall vases branches", "THE EYE GOES UP")
sc("""And you can do it for free this weekend. Go out in the yard with your clippers, and cut tall branches. Bare birch, red twig dogwood, magnolia, pine, even dry hydrangea heads. Put them in two big jars or crocks with some stones in the bottom to hold them up. Then put a big wreath or a mirror in the middle above the garland, and you're done.""",
   "cutting branches yard clippers", "FREE THIS WEEKEND")

sc("""And a word about candles in garland, sweetheart. Real flames and dry branches are a terrible pair. Every December, the fire department in Mansfield used to put a notice in the paper about it. Use battery candles inside the garland, the good ones with the flickering light. Keep any real candles in tall glass holders, well above the greens, and never leave them burning when you leave the room.""",
   "battery candles glass holders mantel", "NEVER REAL FLAMES")

ch("Garland anywhere")
sc("""And garland isn't only for the fireplace, sweetheart. Over the kitchen window. Across the top of a bookshelf. Along the middle of the dinner table, with candles in it. Over the front door, outside. Or across the headboard of the guest bed, with little lights, for the grandchildren. That's their favorite. They say it's like sleeping in the woods.""",
   "garland over kitchen window", "LIKE SLEEPING IN THE WOODS")
sc("""And when you take it down, after the sixth of January, save the best parts. Pull out the lights and wind them around a piece of cardboard, so they don't tangle. Keep the pinecones and dried oranges in a shoebox. Throw the real branches in the yard for the birds. And next year, you start with half the work already done.""",
   "storing Christmas lights cardboard", "HALF THE WORK DONE")

ch("Grandma's garland")
sc("""So one more time. Make it full, twist two together and fluff. Mix in real greens, free from the tree lot. Let it drape at the ends. Tuck warm lights deep inside. Pick three things and repeat them. Swag the stairs, and keep the rail clear. And add height with tall branches. That's how my mother made a piano look like a magazine.""",
   "beautiful Christmas mantel lights", "LIKE A MAGAZINE")
sc("""Tell me in the comments, sweetheart. Real garland, or fake garland? And where do you hang yours? The whole playlist of Grandma's Christmas tips is right there on your screen, and I'll see you in the next video. Good night, honey. Merry Christmas.""",
   "cozy living room Christmas evening", "REAL OR FAKE?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma40", "7 Christmas Garland Mistakes That Make Your Home Look CHEAP",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "Traditional evergreen garlands of cedar, pine, spruce, boxwood and holly in American homes.",
      "Dried orange slices: 1/4 inch slices dried at about 200 F for around 3 hours."],
     "christmas with tips", minutes=(10, 14.5), voice="en_US-lessac-high")
